package net.officefloor.hq.app.pool;

import java.math.BigDecimal;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import net.officefloor.hq.app.setting.SettingsRepository;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.plugin.variable.Val;
import net.officefloor.web.ObjectResponse;

/**
 * The sheet's pot is the pot of each pool that is a member of none; a pool that is a member of another
 * has its cut in that pool as its pot.
 */
public class RespondWithPools {
    public void respond(@Val Sheet sheet, PoolRepository repository, SettingsRepository settings,
            ObjectResponse<PoolsResponse> response) {
        List<PoolMember> members = repository.members(sheet.id());
        BigDecimal sheetPot = settings.find(sheet.id()).pot();
        Map<String, List<PoolMember>> byPool = new HashMap<>();
        for (Pool p : repository.findAll(sheet.id())) {
            byPool.put(p.name(), members.stream().filter(m -> m.pool().equals(p.name())).toList());
        }
        Map<String, BigDecimal> pots = new HashMap<>();
        response.send(new PoolsResponse(repository.findAll(sheet.id()).stream()
                .map(p -> PoolResponse.from(p, byPool.get(p.name()), pot(p.name(), members, byPool, sheetPot, pots)))
                .toList()));
    }

    /** The pool's pot: the sheet's when it is a member of no pool, else its cut in the pool above (null for none). */
    private static BigDecimal pot(String pool, List<PoolMember> members, Map<String, List<PoolMember>> byPool,
            BigDecimal sheetPot, Map<String, BigDecimal> pots) {
        if (pots.containsKey(pool)) return pots.get(pool);
        BigDecimal pot = sheetPot;
        for (PoolMember m : members) {
            if (!pool.equals(m.memberPool())) continue;
            List<PoolMember> above = byPool.get(m.pool());
            List<BigDecimal> cuts = PoolResponse.cutsOf(above, pot(m.pool(), members, byPool, sheetPot, pots));
            pot = cuts == null ? null : cuts.get(above.indexOf(m));
            break;
        }
        pots.put(pool, pot);
        return pot;
    }
}
package net.officefloor.hq.app.pool;

/**
 * A pool member, as the screen reads it: the person's id ('' for a member pool) or the member pool's
 * name ('' for a person), the name, their share, whether they are retired, and their cut of the pool's
 * pot with two decimals ('' for none).
 */
public record PoolMemberResponse(String personId, String memberPool, String name, String share, boolean retired,
        String cut) {
    public static PoolMemberResponse from(PoolMember m, java.math.BigDecimal cut) {
        return new PoolMemberResponse(m.personId() == null ? "" : String.valueOf(m.personId()),
                m.memberPool() == null ? "" : m.memberPool(), m.name(), m.share().toPlainString(), m.retired(),
                cut == null ? "" : cut.toPlainString());
    }
}
import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import { peopleKey } from '../people/people';

/** A person in a pool, or another pool (memberPool its name, personId ''), with a share percent (two decimals). A
 *  retired member's share counts as 0.00 toward the total. Their cut is their part of the pool's pot, two decimals
 *  ('' when the pool is unbalanced or there is no pot). A pool that is a member of no pool has the sheet's pot; one
 *  that is a member of another has its cut there as its pot. */
export type PoolMember = {
  personId: string;
  memberPool: string;
  name: string;
  share: string;
  retired: boolean;
  cut: string;
};

/** A pool on the sheet: its members in the order added, their total share, and balanced when it is exactly 100.00. */
export type Pool = { name: string; members: PoolMember[]; totalShare: string; balanced: boolean };

// Under the people's key: a change to a person (a retirement, a new name) reads the pools again too.
export const poolsKey = (sheetId: string) => [...peopleKey(sheetId), 'pools'] as const;

/** The pools on the sheet, by name. */
export function usePools(sheetId: string) {
  return useQuery({
    queryKey: poolsKey(sheetId),
    queryFn: async () =>
      (await getJson<{ pools: Pool[] }>(`/api/sheets/${encodeURIComponent(sheetId)}/pools`)).pools,
  });
}
